package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.medical.persistence.AgentExecutionPolicyProtocol.*;

/** Synthetic shape fixtures only; none creates a real approval, service identity or business grant. */
final class AgentExecutionPolicySchemaTest {
 private final PermissionSchema json=new PermissionSchema();private final AgentExecutionPolicySchema schema=new AgentExecutionPolicySchema(json);
 AgentExecutionPolicySchemaTest()throws Exception{}
 static String id(int n){return String.format("00000000-0000-4000-8000-%012d",n);}static PermissionProtocol.Basis basis(int n){return new PermissionProtocol.Basis(id(n),"a".repeat(64));}
 DefinitionInput input(){return new DefinitionInput("1.0.0",id(1),"DOCUMENT_BODY","PROJECT_PROFILE",List.of("INTERNAL"),new SourceSelectionInput("FIXED_SOURCE_VERSIONS",List.of()),List.of(),new NetworkPolicyInput(List.of(),false),new Worker("spiffe://test.invalid/runtime","test-runtime-audience"),List.of(new NodeBinding("N00",basis(2),null,null,null,json.object(),List.of(new ActionBinding("TASK","TASK","task.run","TASK_EXECUTION",null,List.of()),new ActionBinding("ARTIFACT","RUN_REGISTERED_ARTIFACT","artifact.read","TASK_EXECUTION",null,List.of("STEP_RESULT"))))),"zh-CN","UTC","test","test-region",false,"2026-10-18T00:00:00Z",null);}
 ObjectNode author(){return (ObjectNode)schema.tree(new Author("1.0.0",input(),"Synthetic schema test"));}
 byte[] bytes(Object value)throws Exception{return schema.canonical(value).getBytes(StandardCharsets.UTF_8);}
 void invalid(Object value){assertThrows(SchemaRejection.class,()->schema.author(bytes(value)));}
 ObjectNode definition(ObjectNode a){return (ObjectNode)a.required("definition");}
 @Test void genuineClosedAuthorInputRoundTrips()throws Exception {var a=schema.author(bytes(author()));assertEquals(input(),a.definition());assertEquals("DOCUMENT_BODY",a.definition().businessPurpose());}
 @Test void serverGeneratesDistinctDomainComponentsAndStableContentHashes()throws Exception {var a=schema.materialize(input());var b=schema.materialize(input());assertNotEquals(a.sourceSelection().version().version_id(),b.sourceSelection().version().version_id());assertEquals(a.sourceSelection().version().content_sha256(),b.sourceSelection().version().content_sha256());assertEquals(2,schema.components(a).size());assertEquals("AGENT_SOURCE_SCOPE_POLICY",AgentExecutionPolicySchema.entityKind("SOURCE_SCOPE"));assertEquals("AGENT_NETWORK_POLICY",AgentExecutionPolicySchema.entityKind("NETWORK_POLICY"));assertEquals(input(),schema.asInput(a));}
 @Test void callersCannotSpecifyGeneratedVersionIdentity() {var a=author();((ObjectNode)definition(a).required("source_selection")).set("version",schema.tree(basis(20)));invalid(a);}
 @Test void unknownFieldsAtEveryClosedLayerReject(){for(String pointer:List.of("","/definition","/definition/worker","/definition/network_policy","/definition/source_selection","/definition/bindings/0","/definition/bindings/0/actions/0")){var a=author();((ObjectNode)a.at(pointer)).put("unapproved",true);invalid(a);}}
 @Test void duplicateKeysTrailingTokensAndMalformedJsonReject()throws Exception {String raw=schema.canonical(author());for(String text:List.of("{",raw+" {}",raw.replaceFirst("\\{","{\"schema_version\":\"1.0.0\",")))assertThrows(SchemaRejection.class,()->schema.author(text.getBytes(StandardCharsets.UTF_8)));}
 @Test void utf8RequestCapIsEnforced(){assertThrows(SchemaRejection.class,()->schema.author(new byte[AgentExecutionPolicySchema.MAXIMUM_BYTES+1]));}
 @Test void blankReasonAndUnknownSchemaReject(){var a=author();a.put("reason","  \t");invalid(a);a=author();a.put("schema_version","2.0.0");invalid(a);}
 @Test void trainingAndExternalNetworkCannotBeEnabled(){var a=author();definition(a).put("training_allowed",true);invalid(a);a=author();((ObjectNode)definition(a).required("network_policy")).put("external_requests_allowed",true);invalid(a);a=author();((ObjectNode)definition(a).required("network_policy")).putArray("https_origins").add("https://test.invalid");invalid(a);}
 @Test void businessPurposeMustBeExplicit(){var a=author();definition(a).remove("business_purpose");invalid(a);a=author();definition(a).put("business_purpose","");invalid(a);}
 @Test void invalidLocaleTimeZoneWorkerUriAndWindowReject(){for(String[] change:List.of(new String[]{"locale","not_a_locale"},new String[]{"timezone","Mars/Unknown"},new String[]{"valid_until","2026-10-17T00:00:00Z"})){var a=author();definition(a).put(change[0],change[1]);invalid(a);}for(String uri:List.of("relative/path","https://user:test@test.invalid","https://test.invalid?q=secret","https://test.invalid/#fragment")){var a=author();((ObjectNode)definition(a).required("worker")).put("service_uri",uri);invalid(a);}}
 @Test void sourceDuplicateIdentityAndMixedHashReject(){var a=author();var sources=((ObjectNode)definition(a).required("source_selection")).putArray("sources");sources.add(schema.tree(basis(30)));sources.add(schema.tree(new PermissionProtocol.Basis(id(30),"b".repeat(64))));invalid(a);}
 @Test void componentIdentityAndHashTamperingReject()throws Exception {var materialized=(ObjectNode)schema.tree(schema.materialize(input()));((ObjectNode)materialized.at("/source_selection/version")).put("content_sha256","b".repeat(64));assertEquals(ErrorCode.CONTENT_MISMATCH,assertThrows(TenantAccessException.class,()->schema.definition(schema.canonical(materialized))).code());}
 @Test void componentCannotAliasDependencyOrAnotherComponent()throws Exception {for(boolean dependency:List.of(false,true)){var d=(ObjectNode)schema.tree(schema.materialize(input()));((ObjectNode)d.at("/network_policy/version")).put("version_id",dependency?id(2):d.at("/source_selection/version/version_id").asText());assertThrows(TenantAccessException.class,()->schema.definition(schema.canonical(d)));}}
 @Test void nodeKindMustBeUnique(){var a=author();((com.fasterxml.jackson.databind.node.ArrayNode)definition(a).required("bindings")).add(definition(a).at("/bindings/0").deepCopy());invalid(a);}
 @Test void onlyN00MayOmitModel(){var a=author();((ObjectNode)definition(a).at("/bindings/0")).put("node_kind","N02");invalid(a);}
 @Test void n00WithoutModelCannotSmuggleParametersOrTokenizer(){var a=author();((ObjectNode)definition(a).at("/bindings/0/generation_parameters")).put("temperature",1);invalid(a);a=author();((ObjectNode)definition(a).at("/bindings/0")).set("tokenizer_version",schema.tree(basis(6)));invalid(a);}
 @Test void modelRequiresActualFixedTokenizerArtifact(){var a=author();((ObjectNode)definition(a).at("/bindings/0")).set("model_version",schema.tree(basis(5)));invalid(a);}
 @Test void actionSelectorCannotBroadenApprovedKindOrAction(){for(String[] change:List.of(new String[]{"resource_kind","PROJECT"},new String[]{"action","task.write"},new String[]{"target_selector","ALL"})){var a=author();((ObjectNode)definition(a).at("/bindings/0/actions/0")).put(change[0],change[1]);invalid(a);}}
 @Test void dynamicArtifactTemplateRequiresExactKnownKindAndReadOnly(){var a=author();((ObjectNode)definition(a).at("/bindings/0/actions/1")).putArray("artifact_kinds");invalid(a);a=author();((ObjectNode)definition(a).at("/bindings/0/actions/1")).putArray("artifact_kinds").add("ANY");invalid(a);a=author();((ObjectNode)definition(a).at("/bindings/0/actions/1")).put("action","artifact.write");invalid(a);}
 @Test void fixedReferenceRequiredOnlyForFixedSelector(){var a=author();((ObjectNode)definition(a).at("/bindings/0/actions/0")).set("fixed_version",schema.tree(basis(7)));invalid(a);a=author();((ObjectNode)definition(a).at("/bindings/0/actions/0")).put("target_selector","FIXED_VERSION").put("action","task.read");invalid(a);}
 @Test void duplicateTemplatesCannotSplitArtifactKinds(){var a=author();var actions=(com.fasterxml.jackson.databind.node.ArrayNode)definition(a).at("/bindings/0/actions");var duplicate=(ObjectNode)actions.get(1).deepCopy();duplicate.putArray("artifact_kinds").add("STEP_ENVELOPE");actions.add(duplicate);invalid(a);}
 @Test void currentPolicySelectorCannotNameAnotherOwnerOrPurpose()throws Exception {var a=author();var action=(ObjectNode)definition(a).at("/bindings/0/actions/0");action.put("resource_kind","CONFIGURATION").put("action","configuration.read").put("target_selector","CURRENT_EXECUTION_POLICY");assertDoesNotThrow(()->schema.author(bytes(a)));action.set("fixed_version",schema.tree(basis(99)));invalid(a);action.putNull("fixed_version");action.put("purpose","AGENT_PUBLICATION");invalid(a);}
 @Test void profileEvidencePurposeIsRequiredAndNotInferred(){var a=author();definition(a).remove("profile_evidence_purpose");invalid(a);a=author();definition(a).put("profile_evidence_purpose"," ");invalid(a);}
 @Test void firstBusinessPurposeIsExactlyDocumentBody(){var a=author();definition(a).put("business_purpose","TASK_EXECUTION");invalid(a);a=author();definition(a).put("business_purpose","AGENT_PUBLICATION");invalid(a);}
 @Test void revisionsArePositiveAndUnsigned64BitBounded()throws Exception {var d=new Decide("1.0.0","1",basis(9),"APPROVE","Synthetic decision");assertEquals(d,schema.decide(bytes(d)));for(String value:List.of("0","-1","18446744073709551616")){var n=(ObjectNode)schema.tree(d);n.put("expected_revision",value);assertThrows(SchemaRejection.class,()->schema.decide(bytes(n)));}}
 @Test void definitionAndNodeCollectionsAreDefensive()throws Exception {var d=schema.materialize(input());assertThrows(UnsupportedOperationException.class,()->d.bindings().clear());var params=d.bindings().get(0).generationParameters();((ObjectNode)params).put("injected",true);assertTrue(d.bindings().get(0).generationParameters().isEmpty());}
 @Test void contentHashesIncludeApprovedPurposeWorkerActionsAndSourceIdentity()throws Exception {String original=schema.hash(input());for(String key:List.of("business_purpose","profile_evidence_purpose","environment","region")){var n=(ObjectNode)schema.tree(input());n.put(key,"OTHER");assertNotEquals(original,schema.hash(n));}}
}
